SELECT dv, COUNT(*) FILTER (WHERE has_ref) * 1.0 / COUNT(*) AS rr FROM (SELECT r.name AS dv, EXISTS (SELECT 1 FROM refunds x WHERE x.order_id = o.order_id) AS has_ref FROM orders o JOIN customer_addresses a USING (address_id) JOIN cities c ON c.city_id = a.city_id JOIN regions r ON r.region_id = c.region_id WHERE o.is_deleted = FALSE AND o.order_at >= TIMESTAMP '2026-01-01 00:00:00' AND o.order_at < TIMESTAMP '2026-02-01 00:00:00' AND o.order_id IN (SELECT order_id FROM payments WHERE status = 'captured')) t GROUP BY dv ORDER BY rr DESC
